import React, { useState, useEffect } from 'react';
import { StyleSheet, View, Text, TouchableOpacity, SafeAreaView, StatusBar, ScrollView, Platform } from 'react-native';
import { AuthProvider, useAuth } from './src/context/AuthContext';
import { SafetyProvider, useSafety } from './src/context/SafetyContext';

import Header from './src/components/Header';
import LoginScreen from './src/screens/LoginScreen';

// Admin Screens
import AdminDashboardScreen from './src/screens/admin/AdminDashboardScreen';
import StudentsScreen from './src/screens/admin/StudentsScreen';
import FleetScreen from './src/screens/admin/FleetScreen';
import RoutesScreen from './src/screens/admin/RoutesScreen';
import MissingStudentsScreen from './src/screens/admin/MissingStudentsScreen';
import SafeDropScreen from './src/screens/admin/SafeDropScreen';
import EmergencyScreen from './src/screens/admin/EmergencyScreen';

// Driver Screens
import DriverHomeScreen from './src/screens/driver/DriverHomeScreen';
import ManifestScreen from './src/screens/driver/ManifestScreen';
import DriverSOSScreen from './src/screens/driver/DriverSOSScreen';

// Parent Screens
import ParentHomeScreen from './src/screens/parent/ParentHomeScreen';
import ParentAttendanceScreen from './src/screens/parent/ParentAttendanceScreen';

// Student Screens
import StudentHomeScreen from './src/screens/student/StudentHomeScreen';

// Common Screens
import LiveTrackingScreen from './src/screens/common/LiveTrackingScreen';
import NotificationsScreen from './src/screens/common/NotificationsScreen';

function MainApp() {
  const { user, isAuthenticated } = useAuth();
  const { activeSOS, missingAlerts, advanceSimulation } = useSafety();
  const [currentTab, setCurrentTab] = useState('home');

  // Reset tab to home if role switches
  useEffect(() => {
    setCurrentTab('home');
  }, [user?.role]);

  if (!isAuthenticated) {
    return <LoginScreen />;
  }

  // Define tab navigation based on role
  const getTabsForRole = () => {
    switch (user?.role) {
      case 'admin':
        return [
          { key: 'home', label: 'Command Center', icon: '📊' },
          { key: 'tracking', label: 'Live Map Radar', icon: '📍' },
          { key: 'students', label: 'Students Roster', icon: '🎓' },
          { key: 'fleet', label: 'Fleet Telematics', icon: '🚌' },
          { key: 'routes', label: 'Routes & Stops', icon: '🗺️' },
          { key: 'safedrop', label: 'Safe-Drop Engine', icon: '🛡️' },
          { key: 'missing', label: 'Missing Alerts', icon: '⚠️', badge: missingAlerts.length },
          { key: 'emergency', label: 'SOS War Room', icon: '🚨', badge: activeSOS ? 1 : 0 },
        ];
      case 'driver':
        return [
          { key: 'home', label: 'Trip Cockpit', icon: '🧭' },
          { key: 'manifest', label: 'RFID Manifest', icon: '📋' },
          { key: 'tracking', label: 'Route Radar', icon: '📍' },
          { key: 'sos', label: 'Panic SOS', icon: '🚨' },
        ];
      case 'parent':
        return [
          { key: 'home', label: 'Child Live Status', icon: '🏠' },
          { key: 'tracking', label: 'Live Bus Radar', icon: '📍' },
          { key: 'attendance', label: 'Journey Logs & Absence', icon: '📅' },
        ];
      case 'student':
        return [
          { key: 'home', label: 'My Digital Pass', icon: '🎒' },
          { key: 'tracking', label: 'Live Bus Radar', icon: '📍' },
        ];
      default:
        return [{ key: 'home', label: 'Command Center', icon: '🏠' }];
    }
  };

  const tabs = getTabsForRole();

  // Render active screen
  const renderScreen = () => {
    if (currentTab === 'notifications') {
      return <NotificationsScreen />;
    }
    if (currentTab === 'tracking') {
      return <LiveTrackingScreen />;
    }

    switch (user?.role) {
      case 'admin':
        switch (currentTab) {
          case 'home': return <AdminDashboardScreen onNavigate={setCurrentTab} />;
          case 'students': return <StudentsScreen />;
          case 'fleet': return <FleetScreen />;
          case 'routes': return <RoutesScreen />;
          case 'missing': return <MissingStudentsScreen />;
          case 'safedrop': return <SafeDropScreen />;
          case 'emergency': return <EmergencyScreen />;
          default: return <AdminDashboardScreen onNavigate={setCurrentTab} />;
        }
      case 'driver':
        switch (currentTab) {
          case 'home': return <DriverHomeScreen onNavigate={setCurrentTab} />;
          case 'manifest': return <ManifestScreen />;
          case 'sos': return <DriverSOSScreen />;
          default: return <DriverHomeScreen onNavigate={setCurrentTab} />;
        }
      case 'parent':
        switch (currentTab) {
          case 'home': return <ParentHomeScreen />;
          case 'attendance': return <ParentAttendanceScreen />;
          default: return <ParentHomeScreen />;
        }
      case 'student':
        switch (currentTab) {
          case 'home': return <StudentHomeScreen />;
          default: return <StudentHomeScreen />;
        }
      default:
        return <AdminDashboardScreen onNavigate={setCurrentTab} />;
    }
  };

  return (
    <SafeAreaView style={styles.safeArea}>
      <StatusBar barStyle="light-content" backgroundColor="#DC2626" />

      {/* Universal Top Mission Header */}
      <Header
        onNotificationPress={() => setCurrentTab('notifications')}
        onEmergencyPress={() => setCurrentTab('emergency')}
        onTabNavigate={setCurrentTab}
      />

      {/* Role Sub-Header / Simulation Controller */}
      <View style={styles.subBar}>
        <View style={styles.subBarLeft}>
          <Text style={styles.roleTag}>{user?.roleTitle || user?.role?.toUpperCase()}</Text>
          <Text style={styles.userGreeting}>
            Active Operator: <Text style={{ fontWeight: '800', color: '#DC2626' }}>{user?.name}</Text>
          </Text>
        </View>
        <TouchableOpacity style={styles.simBtn} onPress={advanceSimulation} activeOpacity={0.8}>
          <Text style={styles.simBtnText}>⚡ Advance Fleet Telemetry</Text>
        </TouchableOpacity>
      </View>

      {/* Navigation Tabs Bar */}
      <View style={styles.navBarContainer}>
        <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.navScroll}>
          {tabs.map((t) => {
            const isActive = currentTab === t.key;
            return (
              <TouchableOpacity
                key={t.key}
                style={[styles.navTab, isActive && styles.navTabActive]}
                onPress={() => setCurrentTab(t.key)}
                activeOpacity={0.8}
              >
                <Text style={styles.tabIcon}>{t.icon}</Text>
                <Text style={[styles.tabLabel, isActive && styles.tabLabelActive]}>{t.label}</Text>
                {t.badge ? (
                  <View style={[styles.tabBadge, isActive && styles.tabBadgeActive]}>
                    <Text style={styles.tabBadgeText}>{t.badge}</Text>
                  </View>
                ) : null}
              </TouchableOpacity>
            );
          })}
        </ScrollView>
      </View>

      {/* Main Content Viewport */}
      <View style={styles.contentContainer}>
        {renderScreen()}
      </View>
    </SafeAreaView>
  );
}

export default function App() {
  return (
    <AuthProvider>
      <SafetyProvider>
        <MainApp />
      </SafetyProvider>
    </AuthProvider>
  );
}

